  bool fa4_ok = (getenv("FA4_NOFA4PAGED")==nullptr) && (hdp==128&&hdvp==128) && (hd==128&&hdv==128)
                && (q.scalar_type()==at::kBFloat16 || q.scalar_type()==at::kHalf) && is_causal
