  int g4_nt = 512; if(const char* e=getenv("FA4_G4NT")) g4_nt=atoi(e);
  int g4_kv = (nb_per_cta>=24) ? 3 : 2; if(const char* e=getenv("FA4_G4KV")) g4_kv=atoi(e);
