          else *(uint4*)&sV[s][voff(key,dv)]=make_uint4(0,0,0,0); }
      asm volatile("cp.async.commit_group;\n");
      asm volatile("cp.async.wait_group 0;\n");   // one wait for the whole block's copies (they pipelined)
